 95	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queues */
 96	static void vTaskButton(void *pvParameters)
 97	{
 98	    (void)pvParameters;
 99	    uint8_t prev_state = 0;
100	
101	    for (;;) {
102	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
103	        if (state && !prev_state) {
104	            uint32_t msg = 1;
105	            if (xButtonQueue != NULL) {
106	                xQueueSend(xButtonQueue, &msg, 0);
107	            }
108	            if (xUIQueue != NULL) {
109	                xQueueSend(xUIQueue, &msg, 0);
110	            }
111	        }
112	        prev_state = state;
113	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
114	    }
115	}
116	
117	/* Task 3: Chờ tín hiệu từ Queue để đổi trạng thái LED3 (PD5) */
118	static void vTaskLED3(void *pvParameters)
119	{
120	    (void)pvParameters;

121	    uint32_t rx_msg = 0;
122	    uint8_t led_state = 0;
123	
124	    for (;;) {
125	        if (xQueueReceive(xButtonQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
126	            led_state = !led_state;
127	            if (led_state) {
128	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
129	            } else {
130	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
131	            }
132	        }
133	    }
134	}
135	
136	/* Task 4: Giám sát hệ thống qua LED4 (PK3) - nhịp tim định kỳ */
137	static void vTaskMonitor(void *pvParameters)
138	{
139	    (void)pvParameters;
140	    for (;;) {
141	        GPIOK->BSRR = (1UL << (LED4_PIN + 16)); /* Bật LED4 */
142	        vTaskDelay(pdMS_TO_TICKS(100));
143	        GPIOK->BSRR = (1UL << LED4_PIN);        /* Tắt LED4 */
144	        vTaskDelay(pdMS_TO_TICKS(1900));
145	    }
146	}
