47	void Reset_Handler(void)
48	{
49	    /* Enable FPU coprocessors CP10 and CP11 (full access) */
50	    SCB->CPACR |= ((3UL << 20) | (3UL << 22));
51	
52	    /* Copy initialized data from Flash to RAM */
53	    uint32_t *pSrc = &_sidata;
54	    uint32_t *pDest = &_sdata;
55	    while (pDest < &_edata) {
56	        *pDest++ = *pSrc++;
57	    }
58	
59	    /* Zero fill the bss section */
60	    uint32_t *pBss = &_sbss;
61	    while (pBss < &_ebss) {
62	        *pBss++ = 0;
63	    }
64	
65	    /* Call the application entry point */
66	    main();
67	
68	    /* Trap if main returns */
69	    while (1);
70	}
